import{_ as r,o as t,c as o,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Developer Summit - BlueStore Part 1","description":"","frontmatter":{"title":"Ceph Developer Summit - BlueStore Part 1","date":"2025-09-12T00:00:00.000Z","updated":"2025-09-12T00:00:00.000Z","tags":["Ceph","Bluestore","distributed storage","storage optimization","performance improvement"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_Developer_Summit_-_BlueStore_Part_1.md","filePath":"posts/2025/Ceph_Developer_Summit_-_BlueStore_Part_1.md","lastUpdated":1780459816000}'),l={name:"posts/2025/Ceph_Developer_Summit_-_BlueStore_Part_1.md"};function s(n,e,i,u,h,g){return t(),o("div",null,[...e[0]||(e[0]=[a('<h3 id="ceph-bluestore-开发会议纪要" tabindex="-1">Ceph Bluestore 开发会议纪要 <a class="header-anchor" href="#ceph-bluestore-开发会议纪要" aria-label="Permalink to &quot;Ceph Bluestore 开发会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>: Bluestore 在 Umbrella 版本中的规划与改进 <strong>主持人</strong>: （未提及姓名） <strong>参会人员</strong>: Bluestore 扩展团队成员、Igor Fedotov（Bluestore 负责人）、Gary Danovich、Ja Prakesh Madaka 等</p><h4 id="会议背景" tabindex="-1"><strong>会议背景</strong> <a class="header-anchor" href="#会议背景" aria-label="Permalink to &quot;**会议背景**&quot;">​</a></h4><p>本次会议主要讨论 Bluestore 在 Umbrella 版本中的技术规划，内容基于 Bluestore 团队的每周二例会（Bluestore Upkeep and Evolution Meeting）的讨论成果。目前多数改进已有初步 PR，但由于 Bluestore 对代码稳定性要求极高，从 PR 到最终合并通常耗时较长。</p><h4 id="主要议题与讨论" tabindex="-1"><strong>主要议题与讨论</strong> <a class="header-anchor" href="#主要议题与讨论" aria-label="Permalink to &quot;**主要议题与讨论**&quot;">​</a></h4><h5 id="_1-roxdb-缓存优化" tabindex="-1"><strong>(1) RoxDB 缓存优化</strong> <a class="header-anchor" href="#_1-roxdb-缓存优化" aria-label="Permalink to &quot;**(1) RoxDB 缓存优化**&quot;">​</a></h5><ul><li><strong>问题</strong>: 现有缓存分片机制存在缺陷，导致超大缓存元素插入时引发持续缓存驱逐。</li><li><strong>解决方案</strong>: 已提交 PR 修复，计划向后兼容（backport）到旧版本。</li><li><strong>重要性</strong>: 关键修复，改善 OMAP 性能。</li></ul><h5 id="_2-fie-map-与零值支持" tabindex="-1"><strong>(2) FIE Map 与零值支持</strong> <a class="header-anchor" href="#_2-fie-map-与零值支持" aria-label="Permalink to &quot;**(2) FIE Map 与零值支持**&quot;">​</a></h5><ul><li><strong>需求</strong>: 区分“未映射的零值”和“客户端显式写入的零值”，对 RBD 和纠删码至关重要。</li><li><strong>挑战</strong>: 纠删码需额外存储零值映射信息，当前处于研究阶段。</li></ul><h5 id="_3-powerpc-大页-64kb-支持" tabindex="-1"><strong>(3) PowerPC 大页（64KB）支持</strong> <a class="header-anchor" href="#_3-powerpc-大页-64kb-支持" aria-label="Permalink to &quot;**(3) PowerPC 大页（64KB）支持**&quot;">​</a></h5><ul><li><strong>问题</strong>: Bluestore 默认假设系统页大小为 4KB，在 PowerPC 上引发直接 I/O 与缓冲 I/O 冲突。</li><li><strong>潜在解决方案</strong>: 改用 direct IO，并开发 Bluestore 专用缓存。</li></ul><h5 id="_4-快速-onode-恢复-fast-onode-recovery" tabindex="-1"><strong>(4) 快速 Onode 恢复（Fast Onode Recovery）</strong> <a class="header-anchor" href="#_4-快速-onode-恢复-fast-onode-recovery" aria-label="Permalink to &quot;**(4) 快速 Onode 恢复（Fast Onode Recovery）**&quot;">​</a></h5><ul><li><strong>问题</strong>: 传统单线程恢复方式耗时过长，导致 OSD 被误判为下线。</li><li><strong>改进</strong>: 多线程恢复显著缩短时间。</li></ul><h5 id="_5-scrub-期间对象优化" tabindex="-1"><strong>(5) Scrub 期间对象优化</strong> <a class="header-anchor" href="#_5-scrub-期间对象优化" aria-label="Permalink to &quot;**(5) Scrub 期间对象优化**&quot;">​</a></h5><ul><li><strong>功能</strong>: 在 Scrub 读取对象时，同步执行重压缩和碎片整理。</li><li><strong>扩展讨论</strong>: 未来可进一步优化对象元数据处理。</li></ul><h5 id="_6-分配映射持久化改进-alloc-map-persistency" tabindex="-1"><strong>(6) 分配映射持久化改进（Alloc Map Persistency）</strong> <a class="header-anchor" href="#_6-分配映射持久化改进-alloc-map-persistency" aria-label="Permalink to &quot;**(6) 分配映射持久化改进（Alloc Map Persistency）**&quot;">​</a></h5><ul><li><strong>问题</strong>: 现有分配映射存储方式在磁盘高度碎片化时效率极低。</li><li><strong>改进</strong>: PR 优化了碎片化场景下的恢复速度。</li></ul><h5 id="_7-性能分析工具-cpu-trace" tabindex="-1"><strong>(7) 性能分析工具（CPU Trace）</strong> <a class="header-anchor" href="#_7-性能分析工具-cpu-trace" aria-label="Permalink to &quot;**(7) 性能分析工具（CPU Trace）**&quot;">​</a></h5><ul><li><strong>用途</strong>: 精确测量代码优化效果，支持小规模渐进式性能提升。</li></ul><h5 id="_8-内存优化-white-overhaul" tabindex="-1"><strong>(8) 内存优化（White Overhaul）</strong> <a class="header-anchor" href="#_8-内存优化-white-overhaul" aria-label="Permalink to &quot;**(8) 内存优化（White Overhaul）**&quot;">​</a></h5><ul><li><strong>目标</strong>: 减少元数据内存占用，提高缓存利用率。</li><li><strong>状态</strong>: 尚未确定具体方案。</li></ul><h4 id="后续行动计划" tabindex="-1"><strong>后续行动计划</strong> <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;**后续行动计划**&quot;">​</a></h4><ol><li><strong>优先级任务</strong>: 合并关键修复 PR，推进 Scrub 优化框架设计。</li><li><strong>研究性工作</strong>: 研究 FIE Map 零值支持的跨模块兼容性，评估 PowerPC 大页支持的长期方案。</li><li><strong>工具与测试</strong>: 推广 CPU Trace 工具，开展内存优化基准测试。</li></ol><h4 id="开放讨论" tabindex="-1"><strong>开放讨论</strong> <a class="header-anchor" href="#开放讨论" aria-label="Permalink to &quot;**开放讨论**&quot;">​</a></h4><p>鼓励社区成员提出未被覆盖的改进方向，或参与每周二的 Bluestore Upkeep and Evolution Meeting。</p>',25)])])}const p=r(l,[["render",s]]);export{d as __pageData,p as default};
